import numpy as np


class Frame:
    """Interface for vector spaces generated by frames"""

    def __init__(self, data: np.ndarray):
        if data.ndim != 3:
            raise ValueError(f"Get data with wrong number of dimensions, "
                             f"should be 3, got {data.ndim}")
        self._rank = data.shape[0]
        self._dim1 = data.shape[1]
        self._dim2 = data.shape[2]
        self.data = data

    # --- geometric properties ---
    @property
    def dim1(self) -> int:
        return self._dim1

    @property
    def dim2(self) -> int:
        return self._dim2

    @property
    def rank(self) -> int:
        return self._rank

    @property
    def shape(self) -> tuple[int, int]:
        return tuple(self.dim1, self.dim2)

    # --- fundamental tensorial algebra ---
    def matrix_times_space(self, mat) -> 'Frame':
        """Left multiplication of the frame elements"""
        # todo : rename contract_physical ?
        if mat.shape[1] != self.dim1:
            raise ValueError(f"Matrix shape {mat.shape} incompatible with "
                             f"dim1 of the Frame: {self.dim1}")
        # mat: (M, N1)
        # data: (R, N1, N2)
        # new_data: (R, M, N2)
        new_data = np.tensordot(mat, self.data,
                                axes=(1, 1)).swapaxes(0, 1)
        return self.__class__(new_data)

    def space_times_matrix(self, mat) -> 'Frame':
        """Change of frame by linear combination"""
        # todo: rename contract_rank
        if mat.shape[0] != self.rank:
            raise ValueError(f"Matrix shape {mat.shape[0]} is incompatible "
                             f"with the representation rank of the "
                             f"Frame: {self.rank}")
        # mat: (R, K)
        # data: (R, N1, N2)
        # new_data: (K, N1, N2)
        new_data = np.tensordot(mat, self.data, axes=(0, 0))
        return self.__class__(new_data)

    def dot(self, other: 'Frame') -> np.ndarray:
        """Compute the Gram matrix between self and other Frame"""
        if self.dim1 != other.dim1 or self.dim2 != other.dim2:
            raise ValueError("Frames must have the same physical dimensions "
                             "to compute Gram matrix.")
        # self.data: (R, N1, N2)
        # other.data: (K, N1, N2)
        # gram: (R, K)
        gram = np.tensordot(self.data, other.data, axes=([1, 2], [1, 2]))
        return gram

    def orth(self) -> tuple['Frame', np.ndarray]:
        """Orthonormalize the frame and return the change of frame matrices"""
        Q, R_fact = np.linalg.qr(self.data.reshape(self.rank, -1).T,
                                 mode="reduced")
        new_data = Q.T.reshape(self.rank, self.dim1, self.dim2)
        return self.__class__(new_data), R_fact


class FrameVector(Frame):
    """
    Specialization of Frame for vectors (states, functions).
    Enforces dim2 == 1.
    """

    def __init__(self, data: np.ndarray):
        super().__init__(data)
        if self.dim2 != 1:
            raise ValueError(
                f"A FrameVector must have an input dimension (dim2) of 1, "
                f"but got {self.dim2}.")

    def subspace(self, dim1_idx) -> 'FrameVector':
        """Extract a sub-frame (evaluate at specific indices)."""
        # self.data: (R, N1, 1)
        # new_data: (R, N2, 1) with N2 = #dim1_idx
        new_data = self.data[:, dim1_idx, :]
        return self.__class__(new_data)

    def unvectorize(self, dim1: int, dim2: int) -> 'FrameOperator':
        """Reshape the vector frame into an operator frame."""
        if dim1 * dim2 != self.dim1:
            raise ValueError(f"Cannot unvectorize dim1={self.dim1} into "
                             f"{dim1}x{dim2}.")

        # (R, N1, 1) --> (R, dim1, dim2)
        new_data = self.data.reshape(self.rank, dim1, dim2)

        return FrameOperator(new_data)

    def to_diagonal_operator(self) -> 'FrameOperator':
        """Convert the vector frame into an operator frame (diagonal matrices)."""
        # (R, N1, 1) -> (R, N1, N1)
        new_data = np.zeros((self.rank, self.dim1, self.dim1), dtype=self.data.dtype)
        idx = np.arange(self.dim1)
        new_data[:, idx, idx] = self.data[:, :, 0]
        return FrameOperator(new_data)


class FrameOperator(Frame):
    """
    Specialization of Frame for operators (matrices mapping N_in to N_out).
    """

    def mtimes(self, other: 'Frame') -> 'Frame':
        """
        Compose this operator with another Frame (Operator or Vector).
        Calculates C = A @ B.
        """
        if self.dim2 != other.dim1:
            raise ValueError(f"Incompatible dimensions for composition: "
                             f"self.dim2={self.dim2} != other.dim1={other.dim1}")

        # self.data  : (R_a, N1, N2)
        # other.data : (R_b, N2, M)
        # new_data: (R_a, R_b, N1, M)
        new_data = np.tensordot(self.data, other.data,
                                axes=(2, 1)).swapaxes(1, 2)

        new_rank = self.rank * other.rank
        # lexicographic ordering on (R_a, R_b) -> new_data (R_a.R_b, N1, M)
        new_data = new_data.reshape(new_rank, self.dim1, other.dim2)
        return other.__class__(new_data)

    def transpose(self, conjugate: bool=False) -> 'FrameOperator':
        """Transpose (or conjugate transpose) the physical dimensions."""
        # data: (R, N_out, N_in)
        # Keep the rank axis (0) intact, swap the physical axes (1 and 2)
        t_data = self.data.transpose(0, 2, 1)

        if conjugate:
            t_data = np.conj(t_data)

        return FrameOperator(t_data)

    @property
    def T(self) -> 'FrameOperator':
        """Syntactic sugar for transpose."""
        return self.transpose(conjugate=False)

    @property
    def H(self) -> 'FrameOperator':
        """Syntactic sugar for conjugate transpose (Hermitian)."""
        return self.transpose(conjugate=True)

    def vectorize(self) -> 'FrameVector':
        """Flatten the operator into a column vector space."""
        # Reshape from (R, N_out, N_in) to (R, N_out * N_in, 1)
        new_dim = self.dim1 * self.dim2
        new_data = self.data.reshape(self.rank, new_dim, 1)

        return FrameVector(new_data)
